import{_ as n,y as i,a as l,o as p,a2 as r,D as s,g as t,I as o}from"./chunks/framework.DCcmcJcL.js";const y=JSON.parse('{"title":"Data Transfer | Bulk Upload","description":"","frontmatter":{},"headers":[],"relativePath":"settings/data-transfer.md","filePath":"settings/data-transfer.md","lastUpdated":1786112796000}'),d={name:"settings/data-transfer.md"};function h(g,e,u,m,c,f){const a=i("ImagePopup");return p(),l("div",null,[e[0]||(e[0]=r('<h1 id="data-transfer-bulk-upload" tabindex="-1">Data Transfer | Bulk Upload <a class="header-anchor" href="#data-transfer-bulk-upload" aria-label="Permalink to &quot;Data Transfer | Bulk Upload&quot;">​</a></h1><p>Bulk import is a feature that allows users to import large quantities of data into a system quickly and efficiently.</p><p>It simplifies the process and saves time by not having to add each piece of information one by one. The feature works differently for each system and has a vast variety of use cases across many industries as well as Bagisto.</p><p>You can easily Bulk Upload <strong>Products, Customers &amp; Tax Rates</strong>.</p><p>From <strong>Bagisto v2.4.9</strong>, saving an import runs it through to the end on its own. Validation, image fetching, record creation, linking, and indexing follow one another automatically, and a stepper at the top of the page shows the live progress of each phase. You no longer have to click through the phases one at a time.</p><h3 id="steps-to-add-bulk-import-in-bagisto" tabindex="-1">Steps to add Bulk Import in Bagisto <a class="header-anchor" href="#steps-to-add-bulk-import-in-bagisto" aria-label="Permalink to &quot;Steps to add Bulk Import in Bagisto&quot;">​</a></h3><p><strong>Step 1:</strong> Go to the Admin panel of Bagisto click on <strong>Settings &gt;&gt; Data Transfer &gt;&gt; Imports</strong> and click on <strong>Create Import</strong> button.</p>',7)),s(a,{src:"/images/settings/import.png",alt:"Import"}),e[1]||(e[1]=r("<p><strong>Step 2:</strong> Under general configurations select the below fields:</p><p><strong>1) Type –</strong> Kindly select the type i.e. (Products, Customers, Tax rates) which you want to import.</p><p><strong>2) File –</strong> Choose the file in your desired format (CSV, XLS, XLSX, XML) and kindly make sure you have all the required fields in the file.</p><p><em>Note – While Import the product data Simple, Configurable, Virtual, Bundled &amp; Grouped product types can be imported except Downloadable products.</em></p><p><strong>3) Download Sample –</strong> You can also download the sample files of types (Products, Customers, Tax Rates). Kindly make sure the file you are uploading is similar to this sample file.</p><p><strong>4) Product Images –</strong> Choose where the images named in your file should be found. This panel is described in detail in the next section, and it appears only for the types that carry images.</p><p><strong>5) Action –</strong> Kindly select from the settings configuration that you want to Create/Update or Delete the records.</p><p><strong>6) Validation Strategy –</strong> This unique feature allows you to Skip the Errors or to Stop on Errors while Importing the data.</p><p><strong>7) Allowed Errors –</strong> This feature allows you how much quantity of errors will get neglected while importing the data.</p><p><strong>8) Field Separator –</strong> This feature allows you to set the fields.</p><p><strong>9) Process in Queue –</strong> This feature allows you to run your import process in a queue. When it is enabled, validation and the image download are dispatched across your queue workers and run in parallel, so a large file is not validated in a single request. Your queue driver has to be set to <code>database</code> or <code>redis</code> for this, otherwise Bagisto asks you to change it before the import can start. When it is disabled, the import runs in short browser-driven windows instead, so no single request runs long enough to time out. Closing the page pauses such a run at the phase it had reached, and reopening the import picks it up from there rather than starting again.</p><p>So now click on the <strong>Import</strong> Button and confirm the message <em>&quot;The import will start as soon as this is saved. Do you want to continue?&quot;</em>.</p>",12)),s(a,{src:"/images/settings/createImport.png",alt:"Create Import"}),e[2]||(e[2]=r('<h3 id="product-images" tabindex="-1">Product Images <a class="header-anchor" href="#product-images" aria-label="Permalink to &quot;Product Images&quot;">​</a></h3><p>While importing products, the images named in your file can come from three different places. Pick the one that matches your file, because the choice is checked against the file during validation — a mismatch is reported as an error instead of silently importing every product without its images.</p><p><strong>1) Image links in the file (Recommended) –</strong> Put the full <code>https://</code> address of each image in the <strong>images</strong> column. Bagisto fetches every link once, in a phase of its own, before any row is written, so nothing has to be placed on the server first.</p><p><strong>2) Upload a ZIP of images –</strong> Upload a single archive containing every image. The <strong>images</strong> column then names the files inside it. You can download a sample archive that matches the sample sheet using the <strong>Download sample images</strong> link, so the two can be tried together. When you reopen an import that already has an archive, the page shows the archive name and how many images are ready; choosing a new archive replaces them.</p><p><strong>3) Images already on the server –</strong> If you have code-base access, place the images in a folder on the server and name that folder in the <strong>Images Directory Path</strong> field. Use a relative path to <code>/project-root/storage/app/import</code>, e.g. <code>product-images</code>. In that case the files should be placed into the <code>/project-root/storage/app/import/product-images</code> folder.</p><p>The method you pick is saved on the import, so reopening it restores the choice along with the value that went with it.</p>',6)),s(a,{src:"/images/settings/importImageSource.png",alt:"Product Images Source"}),e[3]||(e[3]=r("<p><strong>Step 3:</strong> The import now runs on its own and the stepper shows which phase it is in.</p><ul><li><strong>Validate –</strong> The file is read and checked row by row, with a progress bar showing how many rows have been validated.</li><li><strong>Images –</strong> Every image link is fetched before any record is written. This step appears only when you chose <strong>Image links in the file</strong>; an uploaded archive and a server directory are read directly while the rows are written, so they need no separate phase.</li><li><strong>Create / Delete –</strong> The records are written, or removed if the action is <strong>Delete</strong>.</li><li><strong>Link –</strong> The relationships between the imported rows are resolved: configurable variants, grouped product associations, bundle options, booking data, and the related, cross-sell and up-sell links.</li><li><strong>Index –</strong> Price, inventory and Elasticsearch data are rebuilt.</li></ul><p>A delete run has no images to fetch and nothing to link, so those steps are not shown for it.</p>",3)),s(a,{src:"/images/settings/importStepper.png",alt:"Import Stepper"}),e[4]||(e[4]=t("p",null,[o("If the file has errors, the run stops after validation and shows the total rows processed, the invalid rows, and the error count, with a "),t("strong",null,"Download Full Report"),o(" button for the complete list. When the validation strategy is "),t("strong",null,"Skip Errors"),o(" and only some rows are at fault, the import can still proceed and the faulty rows are skipped.")],-1)),e[5]||(e[5]=t("p",null,[t("strong",null,"Step 4:"),o(" Once every phase is complete, the summary confirms the result.")],-1)),s(a,{src:"/images/settings/importDone.png",alt:"Import Done"}),e[6]||(e[6]=t("p",null,"If any batch does not complete, the import finishes the batches it can and reports how many did not, so you can check the error log and run the import again for those rows.",-1)),e[7]||(e[7]=t("p",null,[t("strong",null,"Step 5:"),o(" Now you will able see to all the products under the "),t("strong",null,"Catalog >> Products"),o(" section as shown in the given image.")],-1)),s(a,{src:"/images/settings/importOutput.png",alt:"Import Output"}),e[8]||(e[8]=t("p",null,[o("By the above steps, you can easily create a "),t("strong",null,"Bulk Import"),o(" in Bagisto.")],-1))])}const v=n(d,[["render",h]]);export{y as __pageData,v as default};
